def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort by start endpoint using a new list to avoid mutating the input.
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = [[sorted_intervals[0][0], sorted_intervals[0][1]]]

    for current in sorted_intervals[1:]:
        prev = merged[-1]
        # Merge intervals if the current start is less than or equal to the previous end.
        # This handles touching intervals, overlaps, and nesting.
        if current[0] <= prev[1]:
            prev[1] = max(prev[1], current[1])
        else:
            merged.append([current[0], current[1]])

    return merged

import heapq


def toposort(nodes, edges):
    adj = {node: set() for node in nodes}
    in_degree = {node: 0 for node in nodes}
    seen = set()
    for src, dst in edges:
        if (src, dst) in seen:
            continue
        seen.add((src, dst))
        adj[src].add(dst)
        in_degree[dst] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit must be a positive integer")
    batches = []
    current = []
    total = 0
    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("weight must be a positive integer <= limit")
        if total + weight > limit:
            batches.append(current)
            current = []
            total = 0
        current.append(name)
        total += weight
    if current:
        batches.append(current)
    return batches

import re

_ENV_KEY_RE = re.compile(r'\A[A-Za-z_][A-Za-z0-9_]*\Z')


def parse_env(text):
    """Parse environment assignments from text into a dict."""
    result = {}
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(
                f"Invalid environment assignment (no '='): {line!r}"
            )
        key, _, value = line.partition('=')
        key = key.strip()
        value = value.strip()
        if not _ENV_KEY_RE.match(key):
            raise ValueError(f"Invalid environment key: {key!r}")
        if (
            (value.startswith('"') and value.endswith('"') and len(value) >= 2)
            or (value.startswith("'") and value.endswith("'") and len(value) >= 2)
        ):
            value = value[1:-1]
        result[key] = value
    return result

import math

def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("negative arguments not allowed")
    if base == 0 or cap == 0:
        return 0.0
    # Determine whether base * 2**attempt >= cap without constructing
    # a huge integer or overflowing: compare attempt with log2(cap) - log2(base).
    diff = math.log2(cap) - math.log2(base)
    if attempt >= diff:
        return float(cap)
    # Here base * 2**attempt < cap (mathematically), so it is bounded by
    # cap and cannot overflow. Clamp to handle boundary rounding.
    return min(float(cap), base * 2**attempt)

def fifo_admit(active, queued, budget, slots):
    for q in queued:
        if q > budget:
            raise ValueError("queued reservation exceeds the whole budget")
    admitted = []
    remaining = []
    used_tokens = sum(active)
    used_slots = len(active)
    blocked = False
    for q in queued:
        if blocked or q > budget - used_tokens or used_slots >= slots:
            remaining.append(q)
        else:
            admitted.append(q)
            used_tokens += q
            used_slots += 1
    return admitted, remaining
